  customer_email: b.customer_email || 'customer@example.com',
  case_id: (b.case_id !== undefined && b.case_id !== null) ? b.case_id : ('N8N-' + $execution.id),
  reminder_override: (ov === undefined || ov === null || ov === '') ? null : Number(ov),
  classifyBody: { contents: [{ parts: [{ text: prompt }] }], generationConfig: { responseMimeType: 'application/json', temperature: 0 } }
} }];

