  'Urgent Escalation': ['On-call Supervisor', 'supervisor@sample-company.example'],
  'Needs Human Review': ['Human Review Queue', 'human-review@sample-company.example']
};
const PRIORITY = { 'Complaint': 'High', 'General Enquiry': 'Low', 'Service Request': 'Medium', 'Urgent Escalation': 'Critical', 'Needs Human Review': 'Pending review' };
const FOLLOW = {
  'Complaint': ['2-hour reminder: senior handler checks the complaint is being resolved', 2],
  'General Enquiry': ['No follow-up needed: resolved with an automatic reply', null],
  'Service Request': ['SLA timer: the department actions the request within 1 business day', 24],
  'Urgent Escalation': ['2-hour follow-up by the priority team; automatic resolution paused', 2],
  'Needs Human Review': ['A human agent reviews the case within 4 hours', 4]
};
function finish(base, branch, reply, subtopic, steps0, status, teamOverride, extra) {
  const needsApproval = branch === 'Urgent Escalation' && !!reply;
  const team = teamOverride || TEAMS[branch] || null;
  extra = extra || {};
  const fu = FOLLOW[branch];
  const priority = PRIORITY[branch];
  const steps = steps0.slice();
  if (subtopic) steps.unshift('Classified the sub-topic: ' + subtopic);
  if (reply && needsApproval) steps.push('Held the reply for human approval (not sent yet)');
  else if (reply) steps.push('Sent the reply to ' + base.customer_email + ' (email via n8n)');
  if (team) steps.push('Sent a routing notification to ' + team[0] + ' (Slack)');
  const r = base.result;
  const conf = (typeof r.confidence === 'number') ? r.confidence.toFixed(2) : 'n/a';
  let ack = '';
  if (reply) ack = needsApproval ? 'drafted, held for human approval (not yet sent)' : 'sent to ' + base.customer_email + ' (email via n8n)';
  const dueText = fu[1] === null ? '' : ' (due in ' + fu[1] + ' hours)';
  const lines = [
    'Case #' + base.case_id + ' | ' + branch + ' | PRIORITY: ' + priority,
    'Request: ' + base.request,
    'Type: ' + r.type + ' | Urgency: ' + r.urgency + ' | Confidence: ' + conf,
    'Model reason: ' + r.reason
  ];
  if (ack) lines.push('Customer acknowledgement: ' + ack);
  if (extra.department) { lines.push('Department: ' + extra.department); lines.push('Request details: ' + (extra.summary || '-')); }
  lines.push('Action needed: ' + fu[0] + dueText);
  const body = lines.join('\n');
  const messages = [];
  if (reply) messages.push({ kind: 'Customer reply', to: base.customer_email, subject: 'Re: your request (case #' + base.case_id + ')', body: reply, status: needsApproval ? 'Held - awaiting approval' : 'Sent (email)' });
  if (team) messages.push({ kind: 'Internal notification', to: team[1], subject: '[' + branch + '] Case #' + base.case_id, body, status: 'Sent (Slack)' });
  const ov = base.reminder_override;
  const minutes = fu[1] === null ? null : ((ov !== null && ov !== undefined) ? ov : fu[1] * 60);
  return [{ json: {
    case_id: base.case_id, request: base.request, customer_email: base.customer_email,
    result: r, branch, status, priority, department: extra.department || null, summary: extra.summary || null, needs_approval: needsApproval, subtopic, steps, reply,
    follow_up: fu[0], follow_up_hours: fu[1], reminder_minutes: minutes, messages,
    team: team ? team[0] : null,
    slack_text: team ? ('*[' + branch + '] Case #' + base.case_id + '* to ' + team[0] + '\n' + body) : null
  } }];
}
